    def test_add_unit_with_aliases(self, svc):
        """Line 372: aliases stored."""
        svc.add_unit("length", "nm_custom", "m", 1e-9, aliases=["nano_m"])
        assert "nm_custom" in svc.user_defined_units.get("length", set())

